export function installCanvasStyles(): void {
  if (typeof document === 'undefined' || document.getElementById('xuanling-blueprint-canvas-css')) return
  const style = document.createElement('style')
  style.id = 'xuanling-blueprint-canvas-css'
  style.textContent =
    css +
    collisionControlsCss +
    presentationCss +
    interactionCss +
    compactCss +
    motionCss +
    editorAffordanceCss +
    jsonEditorCss +
    `.bp-workspace .bp-node{height:auto}.bp-workspace .bp-node [data-bp-node-content]{width:100%;display:flow-root}.bp-workspace .bp-node .bp-port-columns>div{flex:1;min-width:0}.bp-workspace .bp-node .bp-port-row{white-space:normal;overflow-wrap:anywhere}.bp-workspace .bp-node-title,.bp-workspace .bp-node-summary,.bp-workspace .bp-node-state,.bp-workspace .bp-node-note{overflow-wrap:anywhere;white-space:normal}` +
    hostControlsCss
  document.head.appendChild(style)
}

// Collision controls occupy a world-independent overlay; ReactFlow keeps its full viewport.
const collisionControlsCss = `
.bp-canvas{position:relative}.bp-layout-apply,.bp-layout-error{position:absolute;z-index:8;top:12px;left:12px;max-width:calc(100% - 24px);background:var(--bp-bg);border:1px solid var(--bp-muted);border-radius:4px}
.bp-layout-apply{min-height:40px}.bp-layout-error{display:flex;align-items:center;flex-wrap:wrap;gap:8px;padding:8px}.bp-layout-error button{min-height:40px}
`
